CREATE TABLE IF NOT EXISTS receipt_image_hash_registry (image_sha256 VARCHAR(64) PRIMARY KEY, table_name VARCHAR(64) UNIQUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receipt_structured_summary (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, receipt_table_name VARCHAR(64) NOT NULL UNIQUE, image_sha256 VARCHAR(64) NOT NULL UNIQUE, store_name VARCHAR(255), branch_name VARCHAR(255), store_category VARCHAR(50), purchased_at TIMESTAMP, total_amount BIGINT, payment_method VARCHAR(100), receipt_number VARCHAR(100), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receipt_structured_item (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, receipt_table_name VARCHAR(64) NOT NULL, item_no INTEGER NOT NULL, item_name TEXT NOT NULL, category VARCHAR(50) NOT NULL, quantity NUMERIC(12,3), unit_price BIGINT, amount BIGINT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (receipt_table_name, item_no));
DELETE FROM receipt_structured_item WHERE receipt_table_name NOT IN (SELECT receipt_table_name FROM receipt_structured_summary);
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_receipt_structured_item_summary') THEN ALTER TABLE receipt_structured_item ADD CONSTRAINT fk_receipt_structured_item_summary FOREIGN KEY (receipt_table_name) REFERENCES receipt_structured_summary(receipt_table_name) ON DELETE CASCADE; END IF; END $$;
